// Generate tests/integration-code.spec.ts from the platform's kit manifests:
//   node gen-code-spec.mjs <integrations.json> <out.spec.ts>
// For every installed integration it checks, in the app's source (REPO_DIR),
// that the kit's files are there, its router is mounted, its pages are routed
// and the app's own code actually uses it. They run with the browser tests, so
// a misplaced integration is a failing test like any other — fixed, redeployed
// and re-checked by the same rounds.
import { readFileSync, writeFileSync } from 'fs';

const [inPath, outPath] = process.argv.slice(2);
const kits = JSON.parse(readFileSync(inPath, 'utf8'));

writeFileSync(
  outPath,
  `// Generated by the platform for this run — do not edit.
import { test, expect } from '@playwright/test';
import { existsSync, readFileSync, readdirSync, statSync } from 'fs';
import { join } from 'path';

const REPO = process.env.REPO_DIR ?? '';
const KITS: Array<{
  provider: string;
  displayName: string;
  files: string[];
  mounts: Array<{ file: string; importLine: string; useLine: string }>;
  pages: Array<{ routePath: string; componentName: string }>;
  usage: string[];
}> = ${JSON.stringify(kits, null, 2)};

const read = (rel: string) => (existsSync(join(REPO, rel)) ? readFileSync(join(REPO, rel), 'utf8') : '');
// Formatting-insensitive: quotes, spacing and semicolons do not matter.
const norm = (s: string) => s.replace(/["\`]/g, "'").replace(/\\s+/g, '').replace(/;/g, '');

// Whole-name match: 'integrations/x' must not match 'integrations/xero'.
function uses(src: string, name: string): boolean {
  for (let i = src.indexOf(name); i >= 0; i = src.indexOf(name, i + 1)) {
    if (!/[A-Za-z0-9_-]/.test(src[i + name.length] ?? '')) return true;
  }
  return false;
}

function sourceFiles(dir: string, out: string[] = []): string[] {
  if (!existsSync(join(REPO, dir))) return out;
  for (const name of readdirSync(join(REPO, dir))) {
    if (name === 'node_modules' || name === 'dist') continue;
    const rel = dir + '/' + name;
    if (statSync(join(REPO, rel)).isDirectory()) sourceFiles(rel, out);
    else if (/\\.(ts|tsx)$/.test(name)) out.push(rel);
  }
  return out;
}

for (const kit of KITS) {
  test.describe('[Integration ' + kit.displayName + '] code', () => {
    test('its files are in the app', () => {
      const missing = kit.files.filter((f) => !existsSync(join(REPO, f)));
      expect(missing, 'integration files missing from the app').toEqual([]);
    });

    if (kit.mounts.length) {
      test('its routes are mounted in the backend', () => {
        for (const m of kit.mounts) {
          const src = norm(read(m.file));
          // The import may have been merged or reordered — the module it comes from is what counts.
          const quoted = m.importLine.match(/['"]([^'"]+)['"]/);
          const from = quoted ? quoted[1] : m.importLine;
          expect(src.includes(norm("from '" + from + "'")), m.file + ' must contain: ' + m.importLine).toBe(true);
          expect(src.includes(norm(m.useLine)), m.file + ' must contain: ' + m.useLine).toBe(true);
        }
      });
    }

    if (kit.pages.length) {
      test('its pages are registered in the frontend router', () => {
        const app = read('frontend/src/App.tsx');
        for (const p of kit.pages) {
          expect(app.includes(p.routePath) && app.includes(p.componentName), 'frontend/src/App.tsx must route ' + p.routePath + ' to ' + p.componentName).toBe(true);
        }
      });
    }

    if (kit.usage.length) {
      test('the app itself uses it (not only installed)', () => {
        const own = new Set([...kit.files, ...kit.mounts.map((m) => m.file)]);
        const users = [...sourceFiles('backend/src'), ...sourceFiles('frontend/src')]
          .filter((f) => !own.has(f))
          .filter((f) => {
            const src = read(f);
            return kit.usage.some((u) => uses(src, u));
          });
        expect(users.length, 'no app file imports the integration (' + kit.usage.join(', ') + ') — the feature is not wired to it').toBeGreaterThan(0);
      });
    }
  });
}
`,
);
